from pathlib import Path
import json,hashlib,numpy as np
R=Path(__file__).resolve().parent;M=json.loads((R/'cut-manifest.json').read_text())
for p,h in M['files'].items():assert hashlib.sha256((R.parent.parent/p).read_bytes()).hexdigest()==h
D=json.loads((R/'cut-results.json').read_text());assert D['status']=='COMPLETED' and len(D['rows'])==240
groups=[]
for mode in ['flat','selective']:
 rows=[r for r in D['rows'] if r['mode']==mode];ok=[r for r in rows if r['base']['status']==r['strengthened']['status']=='OPTIMAL']
 gaps=np.array([max(0,r['strengthened']['dual_upper']-r['MILP']) for r in ok]);old=np.array([max(0,r['LP_odd']-r['MILP']) for r in ok])
 groups.append({'mode':mode,'N':len(rows),'resolved':len(ok),'old_positive_gaps':int(sum(old>1e-7)),'new_positive_gaps':int(sum(gaps>1e-7)),'fractional_LP_solutions':sum(r['strengthened']['fractional_variables']>0 for r in ok),'max_old_gap':float(max(old)),'max_new_gap':float(max(gaps)),'mean_old_gap':float(old.mean()),'mean_new_gap':float(gaps.mean()),'median_base_LP_ms':float(np.median([r['base']['seconds']*1000 for r in ok])),'median_cut_LP_ms':float(np.median([r['strengthened']['seconds']*1000 for r in ok]))})
out={'scope':D['scope'],'elapsed_worker_seconds':D['elapsed'],'external_seconds':json.loads((R/'cut-execution.json').read_text())['wall_seconds'],'groups':groups,'cut_counts':{str(n):next(r['clique_rows'] for r in D['rows'] if r['users']==n) for n in [4,6,8]}}
(R/'cut-summary.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
lines=['# Classical clique strengthening on all prior channel tables','',f"All240 cases completed in {out['external_seconds']:.3f}s external wall time, including startup. These are small fixed-power known-CSI development cases; no new samples were selected.",'','| Mode | N | Positive odd-LP gaps | Positive strengthened gaps | Fractional strengthened solutions | Max old gap | Max new gap | Median base/cut LP ms |','|---|---:|---:|---:|---:|---:|---:|---:|']
for g in groups:lines.append(f"| {g['mode']} | {g['N']} | {g['old_positive_gaps']} | {g['new_positive_gaps']} | {g['fractional_LP_solutions']} | {g['max_old_gap']:.9f} | {g['max_new_gap']:.9f} | {g['median_base_LP_ms']:.3f}/{g['median_cut_LP_ms']:.3f} |")
lines+=['','The four-user/two-resource inequalities are standard conflict-clique cuts. There are6/270/2520 cuts for4/6/8users. Every row passed pairwise-conflict validation. Both LPs passed primal/dual checks and ordering against the previously solved IP. Counts use1e-7 objective tolerance. A fractional solution can attain the same objective as an integer optimum; objective equality does not mean every LP optimum is integral.','', 'Remaining gaps, if any, are retained in cut-results.json. CPU timings include fixed ordering and a single run; no statistical speedup claim. The overhead can exceed the benefit on tiny problems. These results cannot certify variable-power models, scalability or a general polynomial ILP algorithm. Source hashes and the external deadline are recorded in cut-manifest.json and cut-execution.json.','', 'Decision: use the result to assess this bounded LP strengthening only. Publication novelty would need more than applying a known clique inequality; the physical exactness/approximation boundary and independently useful certificate behavior require further prior-art comparison.']
(R/'CUT_REPORT.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
